/* ---------- Ruines d'Alpha : salles intérieures (plus grandes dedans que dehors), d'après les salles de HeartGold/SoulSilver ---------- */
// chaque salle est rangée très loin à l'est de la carte ; entrer par la porte d'un bâtiment y emmène toute l'équipe, la sortie du bas ramène devant la porte
const IN_X0 = 1000000, IN_Y0 = 1000000;
// les quatre salles sont les captures HGSS envoyées par Raphaël, agrandies telles quelles ; le sol praticable (rectangles) et les obstacles (cercles) sont décrits en pixels de la capture
const LAYS = [{"name":"la Salle des Statues","w":120,"h":111,"floor":[[10,29,104,86],[46,86,74,108]],"exit":[46,101,74,111],"entry":[60,92],"puz":[60,42],"solid":[[24,36,6],[24,46,5],[24,70,6],[24,80,5],[96,36,6],[96,46,5],[96,70,6],[96,80,5],[55,59,5],[65,59,5],[55,66,5],[65,66,5],[34,33,3],[78,50,3],[87,62,3],[42,79,3]],"src":"data:image/png;base64,"},{"name":"le Grand Couloir","w":94,"h":120,"floor":[[3,8,91,21],[3,29,91,46],[3,53,91,70],[3,78,91,92],[3,99,91,111],[3,21,22,29],[71,46,91,53],[3,70,22,78],[71,92,91,99],[40,111,54,120]],"exit":[40,113,54,120],"entry":[47,105],"puz":[47,61],"solid":[[7,13,3.5],[20,13,3.5],[33,13,3.5],[46,13,3.5],[59,13,3.5],[72,13,3.5],[85,13,3.5],[7,35,3.5],[20,35,3.5],[33,35,3.5],[46,35,3.5],[59,35,3.5],[72,35,3.5],[85,35,3.5],[7,85,3.5],[20,85,3.5],[33,85,3.5],[46,85,3.5],[59,85,3.5],[72,85,3.5],[85,85,3.5],[7,105,3.5],[20,105,3.5],[33,105,3.5],[46,105,3.5],[59,105,3.5],[72,105,3.5],[85,105,3.5],[7,60,3.5],[85,60,3.5],[56,57,4],[6,24,2.5],[20,24,2.5],[72,49,2.5],[85,49,2.5],[6,73,2.5],[20,73,2.5],[72,96,2.5],[85,96,2.5]],"src":"data:image/png;base64,"},{"name":"la Salle de l'Autel","w":88,"h":120,"floor":[[10,20,80,98],[36,98,50,116]],"exit":[36,109,50,116],"entry":[43,92],"puz":[44,76],"solid":[[28,34,5],[28,42,5],[28,50,5],[36,34,5],[36,42,5],[36,50,5],[44,34,5],[44,42,5],[44,50,5],[52,34,5],[52,42,5],[52,50,5],[60,34,5],[60,42,5],[60,50,5],[75,44,3],[65,50,3],[28,80,3],[13,92,3],[65,92,3]],"src":"data:image/png;base64,"},{"name":"la Salle des Zarbi","w":86,"h":119,"floor":[[8,18,80,99],[37,99,49,118]],"exit":[37,111,49,118],"entry":[43,93],"puz":[43,66],"solid":[[27,26,7],[58,26,7],[42,28,7]],"src":"data:image/png;base64,"}], IK = 12, ICELL = 2; // IK : unités du monde par pixel de capture ; grille de collision de 2 pixels
LAYS.forEach((L, k) => {
  L.x0 = IN_X0 + k * 6000; L.y0 = IN_Y0; L.x1 = L.x0 + L.w * IK; L.y1 = L.y0 + L.h * IK;
  L.img = new Image(); L.img.onload = () => { for (const [key, c] of chunkData) if (inZone(+key.split(",")[0] * CH)) c.canvas = null; }; L.img.src = L.src;
  const gw = Math.ceil(L.w / ICELL), gh = Math.ceil(L.h / ICELL); L.gw = gw; L.gh = gh; L.walk = new Uint8Array(gw * gh); L.floorT = [];
  for (let j = 0; j < gh; j++) for (let i = 0; i < gw; i++) {
    const px = (i + .5) * ICELL, py = (j + .5) * ICELL;
    const ok = L.floor.some(([a, b, c, d]) => px >= a && px <= c && py >= b && py <= d) && !L.solid.some(([x, y, r]) => Math.hypot(px - x, py - y) < r + .5);
    if (ok) { L.walk[j * gw + i] = 1; L.floorT.push({ x:L.x0 + px * IK, y:L.y0 + py * IK }); }
  }
  const P = ([x, y]) => ({ x:L.x0 + x * IK, y:L.y0 + y * IK });
  L.entry = P(L.entry); L.puz = P(L.puz); L.ex = { x0:L.x0 + L.exit[0] * IK, y0:L.y0 + L.exit[1] * IK, x1:L.x0 + L.exit[2] * IK, y1:L.y0 + L.exit[3] * IK };
});
const inZone = x => x > IN_X0 - 3000;
const layAt = (x, y) => LAYS.find(L => x >= L.x0 && x < L.x1 && y >= L.y0 && y < L.y1 + 200) || null;
const layWalk = (L, x, y) => { const i = Math.floor((x - L.x0) / IK / ICELL), j = Math.floor((y - L.y0) / IK / ICELL); return i >= 0 && j >= 0 && i < L.gw && j < L.gh && L.walk[j * L.gw + i] === 1; };

function interiorChunk(ci, cj) { // bords du sol et obstacles des salles : des cercles de collision, marqués « mur » pour arrêter les projectiles
  const x0 = ci * CH, y0 = cj * CH, solids = [], cs = ICELL * IK;
  for (const L of LAYS) {
    if (L.x1 < x0 || L.x0 > x0 + CH || L.y1 < y0 || L.y0 > y0 + CH) continue;
    for (let j = -1; j <= L.gh; j++) for (let i = -1; i <= L.gw; i++) {
      const x = L.x0 + (i + .5) * cs, y = L.y0 + (j + .5) * cs, w = (a, b) => a >= 0 && b >= 0 && a < L.gw && b < L.gh && L.walk[b * L.gw + a] === 1;
      if (x < x0 || x >= x0 + CH || y < y0 || y >= y0 + CH || w(i, j)) continue;
      let edge = false; for (let a = -1; a <= 1 && !edge; a++) for (let b = -1; b <= 1; b++) if (w(i + a, j + b)) { edge = true; break; }
      if (edge) solids.push({ x, y, r:cs * .72, wall:true });
    }
    for (const [sx, sy, r] of L.solid) { const x = L.x0 + sx * IK, y = L.y0 + sy * IK; if (x >= x0 && x < x0 + CH && y >= y0 && y < y0 + CH) solids.push({ x, y, r:r * IK * .85, wall:true }); }
  }
  return { ponds:[], trees:[], rocks:[], logs:[], mounds:[], ruins:[], tablets:[], solids, canvas:null, used:0 };
}
function renderInteriorChunk(ci, cj) { // la capture de la salle, agrandie en douceur, sur fond noir
  const c = getChunk(ci, cj), x0 = ci * CH, y0 = cj * CH, cv2 = document.createElement("canvas"); cv2.width = cv2.height = CH * CH_SCALE;
  const g = cv2.getContext("2d"); g.scale(CH_SCALE, CH_SCALE); g.translate(-x0, -y0);
  g.fillStyle = "#050302"; g.fillRect(x0, y0, CH, CH);
  g.imageSmoothingEnabled = true; g.imageSmoothingQuality = "high";
  for (const L of LAYS) {
    if (L.x1 < x0 || L.x0 > x0 + CH || L.y1 < y0 || L.y0 > y0 + CH) continue;
    if (L.img.complete && L.img.naturalWidth) g.drawImage(L.img, L.x0, L.y0, L.w * IK, L.h * IK);
    const e = L.ex, gr = g.createLinearGradient(0, e.y0, 0, e.y1); gr.addColorStop(0, "rgba(255,235,180,0)"); gr.addColorStop(1, "rgba(255,235,180,.35)"); g.fillStyle = gr; g.fillRect(e.x0, e.y0, e.x1 - e.x0, e.y1 - e.y0); // la lumière du dehors, à la sortie
  }
  c.canvas = cv2; return cv2;
}
function alphPlace(f) { // un Pokémon apparu dans le vide ou dans un mur d'une salle : posé sur une dalle libre, loin des joueurs
  const P = nearP(f.x, f.y), L = P && inZone(P.x) ? layAt(P.x, P.y) : null;
  if (!L) return;
  if (layAt(f.x, f.y) === L && layWalk(L, f.x, f.y)) return;
  let best = null, bd = -1;
  for (let k = 0; k < 24; k++) { const t = L.floorT[Math.random() * L.floorT.length | 0], d = Math.min(...S.players.map(q => Math.hypot(q.x - t.x, q.y - t.y))); if (d > bd) { bd = d; best = t; } if (d > 420) break; }
  if (!best) return;
  f.x = best.x + (Math.random() - .5) * 20; f.y = best.y + (Math.random() - .5) * 20;
  if (!f.prop) S.fxs.push({ x:f.x, y:f.y, r:0, max:f.r * 2, life:.3, col:"rgba(200,170,255," });
}
function teleportTeam(x, y) { // toute l'équipe passe la porte ensemble ; les tirs en vol disparaissent
  S.players.forEach((q, k) => { q.x = x + (k - (S.players.length - 1) / 2) * 34; q.y = y; q.inv = Math.max(q.inv, .6); q.doorCd = .8; });
  S.cam = { x, y }; S.eshots = []; S.blackT = .45;
}
function updateDoors(dt) { // entrer dans un bâtiment par sa porte, ressortir par le bas de la salle
  const P = S.players.find(q => !q.down);
  if (!P) return;
  for (const q of S.players) q.doorCd = Math.max(0, (q.doorCd || 0) - dt);
  if (P.doorCd > 0) return;
  if (inZone(P.x)) {
    const L = layAt(P.x, P.y);
    if (L && P.x > L.ex.x0 && P.x < L.ex.x1 && P.y > L.ex.y0) { const o = S.inside && S.inside.ruin; if (o) teleportTeam(o.ax, o.box.y1 + 46); else teleportTeam(0, START_Y); S.inside = null; }
    return;
  }
  let door = null;
  around(P.x, P.y, c => { for (const o of c.ruins || []) if (Math.abs(P.x - o.ax) < BL_DOOR * BL.U && P.y > o.box.y1 - 10 && P.y < o.box.y1 + 34) door = o; });
  if (!door) return;
  const L = LAYS[door.lay];
  S.inside = { ruin:door, lay:door.lay }; teleportTeam(L.entry.x, L.entry.y);
  banner(`Tu entres dans ${L.name}.`);
}
const alphWall = (x, y) => solidsNear(x, y).some(o => o.wall && (x - o.x) ** 2 + (y - o.y) ** 2 < o.r * o.r);
